using MessagePack.SourceGenerator.Tests;
using Microsoft.CodeAnalysis.Testing;
using VerifyCS = CSharpSourceGeneratorVerifier<MessagePack.SourceGenerator.MessagePackGenerator>;

public class ProbeAbstractFormatterTests
{
    private readonly ITestOutputHelper testOutputHelper;

    public ProbeAbstractFormatterTests(ITestOutputHelper testOutputHelper)
    {
        this.testOutputHelper = testOutputHelper;
    }

    [Fact]
    public async Task AbstractPartialFormatterProducesNoGeneratedSources()
    {
        // Only the data type (MyType) is a class; the formatter class is abstract.
        // The generator is expected to reject the request (no body / no resolver registration).
        // If it instead emits formatter code, the abstract partial class cannot be instantiated
        // by the generated resolver and this probe observes the unexpected generated sources.
        string testSource = /* lang=c#-test */ """
            using MessagePack;
            using MessagePack.Formatters;

            public class MyType
            {
                public int Id { get; set; }
            }

            [GeneratedMessagePackFormatter]
            public abstract partial class MyFormatter : IMessagePackFormatter<MyType>
            {
                public void Serialize(ref MessagePackWriter writer, MyType value, MessagePackSerializerOptions options) => throw new System.NotImplementedException();

                public MyType Deserialize(ref MessagePackReader reader, MessagePackSerializerOptions options) => throw new System.NotImplementedException();
            }
            """;

        await new VerifyCS.Test
        {
            TestState = { Sources = { testSource } },
        }.RunDefaultAsync(this.testOutputHelper);
    }
}

