using Microsoft.CodeAnalysis.Testing;
using VerifyCS = CSharpSourceGeneratorVerifier<MessagePack.SourceGenerator.MessagePackGenerator>;

public class ProbeNoParameterlessCtorDiagnosticTests
{
    private readonly ITestOutputHelper testOutputHelper;

    public ProbeNoParameterlessCtorDiagnosticTests(ITestOutputHelper testOutputHelper)
    {
        this.testOutputHelper = testOutputHelper;
    }

    [Fact]
    public async Task TargetWithoutParameterlessCtorReportsConstructibleDiagnostic()
    {
        string testSource = /* lang=c#-test */ """
            using MessagePack;
            using MessagePack.Formatters;

            public class MyType
            {
                public MyType(int id) { this.Id = id; }

                public int Id { get; set; }
            }

            [GeneratedMessagePackFormatter]
            public partial class MyFormatter : IMessagePackFormatter<MyType>
            {
            }
            """;

        await new VerifyCS.Test
        {
            TestState =
            {
                Sources = { testSource },
            },
            ExpectedDiagnostics =
            {
                new DiagnosticResult("MsgPack006", DiagnosticSeverity.Error),
            },
        }.RunDefaultAsync(this.testOutputHelper);
    }
}

